using Aspose.Cells;
using System;
using System.IO;
using System.Text.RegularExpressions;

// The sample creates a workbook, saves it to HTML, then uses a regular expression to locate every self‑closing tag and appends a data-tablecssid attribute with a specified identifier, skipping tags that already contain the attribute, and writes the modified HTML to a file.
class Program
{
    static void Main()
    {
        // Create a new workbook and add some sample data
        Workbook workbook = new Workbook();
        Worksheet sheet = workbook.Worksheets[0];
        sheet.Cells["A1"].PutValue("Sample");
        sheet.Cells["A2"].PutValue("Data");

        // Identifier that should prefix self‑closing tags
        string tableCssId = "myTable";

        // Save the workbook to HTML in a memory stream
        using (MemoryStream htmlStream = new MemoryStream())
        {
            HtmlSaveOptions htmlOptions = new HtmlSaveOptions();
            workbook.Save(htmlStream, htmlOptions);
            htmlStream.Position = 0;
            string htmlContent = new StreamReader(htmlStream).ReadToEnd();

            // Regex to locate self‑closing tags (e.g., <img .../>)
            string selfClosingPattern = @"<(?<tag>\w+)(?<attrs>[^>]*?)\s*/>";
            string updatedHtml = Regex.Replace(htmlContent, selfClosingPattern, match =>
            {
                string tagName = match.Groups["tag"].Value;
                string attributes = match.Groups["attrs"].Value;

                // If the tag already contains the identifier, leave it unchanged
                if (Regex.IsMatch(attributes, @"\bdata-tablecssid\s*=", RegexOptions.IgnoreCase))
                    return match.Value;

                // Append the identifier as a data attribute before the closing slash
                string newAttributes = attributes + $" data-tablecssid=\"{tableCssId}\"";
                return $"<{tagName}{newAttributes}/>";
            }, RegexOptions.IgnoreCase);

            // Write the modified HTML to a file
            File.WriteAllText("ModifiedOutput.html", updatedHtml);
        }
    }
}
